// Step-specific "what to type" content for the core ISO 9001 steps of E2E-01 (context,
// policy, objectives, process architecture). Each entry returns the form values a trained
// IMS manager would record, so the seeded runs and the user guides show useful outputs
// instead of generic text. Placeholders: {org} {product} {line} {city} {customer} {supplier}
// {d0} {d1} {d2} (profile defects) and {std}. All organizations and people are fictional.
import { addDays } from './rng.js';

const L = (en, fr, ar) => ({ en, fr, ar });
export function fv(t, v) {
  if (!t || typeof t !== 'object') return t;
  const out = {};
  for (const l of ['en', 'fr', 'ar']) out[l] = (t[l] ?? t.en).replace(/\{(\w+)\}/g, (m, k) => { const x = v[k]; if (x === undefined || x === null) return m; return typeof x === 'object' ? (x[l] ?? x.en) : String(x); });
  return out;
}
const row = (item, category, detail, priority, source) => ({ item, category, detail, priority, source });
const crit = (criterion, weight, score, justification) => ({ criterion, weight, score, justification });

// Categories
const C = {
  eco: L('Economic', 'Économique', 'اقتصادي'), mkt: L('Market and customers', 'Marché et clients', 'السوق والعملاء'), reg: L('Legal and regulatory', 'Légal et réglementaire', 'قانوني وتنظيمي'),
  tech: L('Technological', 'Technologique', 'تقني'), sup: L('Supply', 'Approvisionnement', 'التوريد'), env: L('Environmental', 'Environnemental', 'بيئي'), soc: L('Social', 'Social', 'اجتماعي'),
  proc: L('Process', 'Processus', 'العملية'), com: L('Commercial', 'Commercial', 'تجاري'), res: L('Resources', 'Ressources', 'الموارد'), comp: L('Competence', 'Compétences', 'الكفاءات'), info: L('Information', 'Information', 'المعلومات'),
  ext: L('External party', 'Partie externe', 'طرف خارجي'), int: L('Internal party', 'Partie interne', 'طرف داخلي'),
  iface: L('Interface', 'Interface', 'واجهة'), scope: L('Scope statement', 'Énoncé du périmètre', 'بيان النطاق'), site: L('Site', 'Site', 'الموقع'), excl: L('Non-applicable requirement', 'Exigence non applicable', 'متطلب غير منطبق'), out: L('Outsourced process', 'Processus externalisé', 'عملية مسندة لجهة خارجية'),
  std: L('Standard', 'Norme', 'المعيار'), commit: L('Commitment', 'Engagement', 'الالتزام'), dir: L('Strategic direction', 'Orientation stratégique', 'التوجه الاستراتيجي'),
  mgmt: L('Management process', 'Processus de management', 'عملية إدارية'), core: L('Core process', 'Processus de réalisation', 'عملية أساسية'), supp: L('Support process', 'Processus support', 'عملية داعمة'),
};


// Interested parties of MP-001.4 (same labels, so needs map to them) and their needs (MP-001.5).
const PARTY = {
  cust: (c) => fv(L('Customers ({customer})', 'Clients ({customer})', 'العملاء ({customer})'), c.v), staff: () => L('Employees and their representatives', 'Salariés et leurs représentants', 'الموظفون وممثلوهم'),
  owner: () => L('Owner and shareholders', 'Dirigeant et actionnaires', 'المالك والمساهمون'), sup: (c) => fv(L('Suppliers of {supplier}', 'Fournisseurs de {supplier}', 'موردو {supplier}'), c.v),
  cb: () => L('Certification body', 'Organisme de certification', 'جهة الاعتماد'), auth: () => L('Authorities (labour inspection, municipality)', 'Autorités (inspection du travail, commune)', 'السلطات (مفتشية الشغل، البلدية)'),
};
const TYPE = {
  contract: L('Contractual requirement', 'Exigence contractuelle', 'متطلب تعاقدي'), legal: L('Legal or regulatory requirement', 'Exigence légale ou réglementaire', 'متطلب قانوني أو تنظيمي'),
  expect: L('Customer expectation', 'Attente client', 'توقع العميل'), internal: L('Internal expectation', 'Attente interne', 'توقع داخلي'), vol: L('Voluntary commitment', 'Engagement volontaire', 'التزام طوعي'),
};
const need = (c, text, parties, type, obligation, response, priority, origin, source) => ({ need: text, parties: parties.map(k => ({ id: null, name: PARTY[k](c) })), type, obligation, response, priority, origin, source });
export function needsRows(c) {
  return [
    need(c, L('Service delivered on the agreed date, right first time', 'Prestation réalisée à la date convenue, bien du premier coup', 'تقديم الخدمة في الموعد المتفق عليه وبشكل صحيح من المرة الأولى'), ['cust'], TYPE.contract, 'Yes', L('Planning and job order control (service delivery process); KPI on-time service', 'Planification et maîtrise des ordres de travail (processus de réalisation) ; KPI ponctualité', 'التخطيط وضبط أوامر العمل (عملية تقديم الخدمة)؛ مؤشر الالتزام بالموعد'), 'High', 'Manual', L('Framework contracts; satisfaction survey 2025', 'Contrats-cadres ; enquête de satisfaction 2025', 'العقود الإطارية؛ استبيان الرضا 2025')),
    need(c, L('Correct quotes and clear invoices', 'Devis justes et factures claires', 'عروض أسعار صحيحة وفواتير واضحة'), ['cust', 'owner'], TYPE.expect, 'No', L('Quote review before sending; invoice checked against the signed job sheet', 'Revue du devis avant envoi ; facture contrôlée avec la fiche signée', 'مراجعة العرض قبل إرساله؛ ومطابقة الفاتورة مع بطاقة العمل الموقعة'), 'High', 'Manual', L('Quotation register: 9 corrections in Q3 2025', 'Registre des devis : 9 corrections au T3 2025', 'سجل العروض: 9 تصحيحات في الربع الثالث 2025')),
    need(c, L('ISO 9001 certification within 12 months', 'Certification ISO 9001 sous 12 mois', 'الحصول على شهادة ISO 9001 خلال 12 شهرًا'), ['cust', 'owner', 'cb'], TYPE.vol, 'Yes', L('QMS project AT-UNI-QMS; certification audit planned', 'Projet SMQ ; audit de certification planifié', 'مشروع نظام إدارة الجودة؛ تدقيق الاعتماد مخطط'), 'High', 'Library', L('Tender files 2025; business plan 2025–2027', 'Appels d\'offres 2025 ; plan d\'affaires 2025–2027', 'ملفات المناقصات 2025؛ خطة الأعمال 2025–2027')),
    need(c, L('Safe work, training and clear work instructions', 'Travail en sécurité, formation et instructions claires', 'عمل آمن وتدريب وتعليمات عمل واضحة'), ['staff'], TYPE.legal, 'Yes', L('Training plan (MP-013) and work instructions (MP-006)', 'Plan de formation (MP-013) et instructions de travail (MP-006)', 'خطة التدريب (MP-013) وتعليمات العمل (MP-006)'), 'High', 'Library', L('Labour code; staff meeting minutes, October 2025', 'Code du travail ; réunion du personnel, octobre 2025', 'مدونة الشغل؛ محضر اجتماع الموظفين، أكتوبر 2025')),
    need(c, L('Workload planned during peaks', 'Charge de travail planifiée pendant les pics', 'تخطيط عبء العمل في أوقات الذروة'), ['staff', 'owner'], TYPE.internal, 'No', L('Capacity planning reviewed weekly; seasonal staff', 'Planification de capacité revue chaque semaine ; saisonniers', 'مراجعة تخطيط القدرة أسبوعيًا؛ عمالة موسمية'), 'Medium', 'AI', L('Planning board and overtime records', 'Planning et relevés d\'heures supplémentaires', 'لوحة التخطيط وسجلات الساعات الإضافية')),
    need(c, L('Forecast of needs and payment on time', 'Prévision des besoins et paiement à l\'échéance', 'توقع الاحتياجات والسداد في الموعد'), ['sup'], TYPE.contract, 'No', L('Quarterly forecast shared; payment terms 60 days', 'Prévision trimestrielle partagée ; paiement à 60 jours', 'مشاركة التوقعات الفصلية؛ السداد خلال 60 يومًا'), 'Medium', 'Manual', L('Supplier meetings, 2025', 'Réunions fournisseurs, 2025', 'اجتماعات الموردين، 2025')),
    need(c, L('Access to records and people during audits', 'Accès aux enregistrements et aux personnes pendant les audits', 'إتاحة الوصول إلى السجلات والأشخاص أثناء التدقيق'), ['cb'], TYPE.contract, 'Yes', L('Records control (MP-030); audit coordination (MP-017)', 'Maîtrise des enregistrements (MP-030) ; coordination d\'audit (MP-017)', 'ضبط السجلات (MP-030)؛ تنسيق التدقيق (MP-017)'), 'Medium', 'Library', L('Certification contract', 'Contrat de certification', 'عقد الاعتماد')),
    need(c, L('Compliance with labour law, business licence and waste rules', 'Respect du droit du travail, de l\'autorisation d\'exercer et des règles sur les déchets', 'الامتثال لقانون الشغل ورخصة المزاولة وقواعد النفايات'), ['auth', 'staff'], TYPE.legal, 'Yes', L('Legal register and compliance evaluation (MP-028)', 'Registre réglementaire et évaluation de conformité (MP-028)', 'السجل القانوني وتقييم الامتثال (MP-028)'), 'Medium', 'AI', L('Legal register', 'Registre réglementaire', 'السجل القانوني')),
  ];
}

