// SMART objectives of a run (MP-003), consistent with the objectives register.
export function smartObjectives(c) {
  const k = (code) => c.kpiByCode[code];
  const mk = (objective, code, baseline, relevance, ownerRole, months, resources) => ({
    objective, kpi: k(code)?.id || null, baseline, target: k(code)?.targetText || '', relevance, owner: c.user(ownerRole), deadline: addDays(c.start, 30 * months), resources,
  });
  const list = [
    mk(fv(L('Raise customer satisfaction on {product}', 'Augmenter la satisfaction client sur les {product}', 'رفع رضا العملاء عن {product}'), c.v), 'Q-KPI-01', '78%', L('Satisfy customer requirements', 'Satisfaire les exigences clients', 'تلبية متطلبات العملاء'), 'quality_manager', 12, L('Quarterly survey; complaint review meeting', 'Enquête trimestrielle ; réunion de revue des réclamations', 'استبيان ربع سنوي؛ اجتماع مراجعة الشكاوى')),
    mk(fv(L('Deliver {product} on time', 'Réaliser les {product} dans les délais', 'تقديم {product} في الموعد'), c.v), 'Q-KPI-02', '86%', L('On time, right first time', 'À temps, du premier coup', 'في الموعد ومن المرة الأولى'), 'operations_manager', 9, L('Planning board; one extra technician in summer', 'Planning ; un technicien de plus l\'été', 'لوحة التخطيط؛ فني إضافي في الصيف')),
    mk(L('Reduce the cost of poor quality', 'Réduire le coût de la non-qualité', 'خفض تكلفة ضعف الجودة'), 'Q-KPI-04', '4.1%', L('Continual improvement', 'Amélioration continue', 'التحسين المستمر'), 'quality_manager', 12, L('Rework tracking in the NC register', 'Suivi des reprises dans le registre NC', 'تتبع إعادة العمل في سجل عدم المطابقة')),
    mk(L('Close corrective actions on time', 'Clôturer les actions correctives à temps', 'إغلاق الإجراءات التصحيحية في موعدها'), 'Q-KPI-05', '70%', L('Continual improvement', 'Amélioration continue', 'التحسين المستمر'), 'ims_manager', 6, L('Weekly action review', 'Revue hebdomadaire des actions', 'مراجعة أسبوعية للإجراءات')),
  ];
  return list.filter(o => o.kpi);
}
